#!/bin/bash
# runner5 (E26): the tie after the udel change -- LeanP1Anc.tla (regenerated by
# make-anc.py) must have exactly LeanP1.tla's distinct states on Holds1p3b
# (461,094,969 before the change), every invariant checked on both.
BK=flint-tlc-m5-20261013; W=/work; mkdir -p $W/e26; cd $W/e26
export HOME=/root; . /root/.cargo/env
aws s3 cp s3://$BK/in5/ $W/e26/ --recursive --exclude 'runner5.sh'
echo "RUNNER5 $(date -u +%FT%TZ) $(md5sum LeanP1.tla LeanP1Anc.tla | cut -c1-32 | tr '\n' ' ')" >> $W/out/RESULTS.txt
PIDS=""
for x in "TieP1 LeanP1" "TieAnc LeanP1Anc"; do
  set -- $x; n=$1; mod=$2
  mkdir -p $W/cache/E26$n $W/meta/E26$n
  ( ( time TLAMC_CACHE=$W/cache/E26$n timeout 9000 tla-mc -compile -workers 24 -queue-mem 16000 -fpmem 12000 -checkpoint 0 -metadir $W/meta/E26$n -config E26$n.cfg $mod.tla ) > $W/out/E26$n.out 2>&1
    rc=$?; echo "rc=$rc $(date -u +%H:%M:%SZ)" >> $W/out/E26$n.out
    echo "E26$n rc=$rc $(grep -h -E 'violated|distinct states found' $W/out/E26$n.out | tr '\n' ' ')" >> $W/out/RESULTS.txt; rm -rf $W/meta/E26$n ) &
  PIDS="$PIDS $!"
done
wait $PIDS
echo "DONE5 $(date -u +%FT%TZ)" >> $W/out/RESULTS.txt
